window.OPUS_PAGES = window.OPUS_PAGES || {};
window.OPUS_PAGES["020"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Long Water — The World's Great Rivers</title>\n<meta name=\"description\" content=\"A data-art atlas of the ten longest rivers on Earth, each drawn as a meandering ribbon to scale, with drifting current, unit and sort toggles, and a droplet race that lets you feel the differences in length.\">\n<meta name=\"theme-color\" content=\"#f3f1ec\">\n<style>\n:root{\n  --lime:#f3f1ec;\n  --lime-2:#ebe7de;\n  --lime-3:#dfdad0;\n  --ink:#1c272e;\n  --ink-2:#4d5a62;\n  --ink-3:#848d92;\n  --hair:rgba(28,39,46,.15);\n  --hair-2:rgba(28,39,46,.08);\n  --deep:#0b3d5c;\n  --mid:#1f7a90;\n  --shoal:#7fc8c2;\n  --serif:\"Baskerville\",\"Baskerville Old Face\",\"Hoefler Text\",\"Garamond\",\"Yrsa\",\"P052\",\"Palatino Linotype\",Georgia,serif;\n  --pad:clamp(16px,3.9vw,56px);\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;overflow-x:clip}\nbody{\n  margin:0;\n  background-color:var(--lime);\n  color:var(--ink);\n  font-family:var(--serif);\n  font-size:17px;\n  line-height:1.55;\n  font-variant-numeric:lining-nums tabular-nums;\n  overflow-x:hidden;\n  -webkit-font-smoothing:antialiased;\n}\n#paper{position:fixed;left:0;top:0;width:100%;height:100%;z-index:-1;pointer-events:none}\n#chart:focus,.chart-wrap:focus{outline:none}\n.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n.skip{position:absolute;left:12px;top:-60px;background:var(--deep);color:var(--lime);padding:8px 14px;border-radius:2px;z-index:20;text-decoration:none}\n.skip:focus{top:12px}\n:focus-visible{outline:2px solid var(--deep);outline-offset:3px}\n\n/* ——— masthead ——— */\n.mast{\n  padding:clamp(14px,2vw,26px) var(--pad) 0;\n  display:grid;\n  grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);\n  gap:clamp(14px,2.6vw,52px) clamp(18px,3.4vw,64px);\n  align-items:end;\n}\n.kicker{\n  grid-column:1/-1;\n  display:flex;justify-content:space-between;align-items:center;gap:16px;\n  font-variant:small-caps;letter-spacing:.14em;font-size:13px;color:var(--ink-2);\n  text-transform:lowercase;\n  border-bottom:1px solid var(--hair);padding-bottom:10px;\n}\n.kicker span:last-child{color:var(--ink-3)}\n.title-block{position:relative;padding-top:6px;isolation:isolate}\n.contours{position:absolute;left:-2%;top:-18%;width:108%;height:140%;z-index:-1;pointer-events:none;overflow:visible}\n.contours use{fill:none;stroke:#7fc8c2;stroke-width:1;opacity:.42}\n.contours use:nth-child(odd){stroke:#1f7a90;opacity:.16}\nh1{\n  margin:0;position:relative;\n  font-weight:400;font-style:italic;\n  font-size:clamp(54px,8.2vw,128px);\n  line-height:.88;letter-spacing:-.02em;\n  color:var(--deep);\n  text-shadow:0 0 18px var(--lime),0 0 6px var(--lime);\n}\nh1 .amp{font-style:normal;color:var(--ink-3);font-size:.5em;vertical-align:.32em;margin:0 .06em}\n.subtitle{\n  margin:.55em 0 0;\n  font-variant:small-caps;text-transform:lowercase;letter-spacing:.2em;\n  font-size:clamp(13px,1.2vw,16px);color:var(--ink-2);\n  display:flex;align-items:center;gap:14px;\n}\n.subtitle svg{flex:0 0 auto}\n.wave-orn path{stroke-dasharray:120;stroke-dashoffset:120;animation:draw 1.3s cubic-bezier(.3,.7,.2,1) forwards}\n.wave-orn path:nth-child(2){animation-delay:.12s}\n.wave-orn path:nth-child(3){animation-delay:.24s}\n@keyframes draw{to{stroke-dashoffset:0}}\n\n.intro{max-width:640px;justify-self:end}\n.intro p{margin:0 0 10px;font-size:clamp(15px,1.08vw,16.5px);color:var(--ink-2);hyphens:auto;line-height:1.52}\n.intro p:first-child::first-letter{\n  float:left;font-size:3.1em;line-height:.82;padding:.06em .08em 0 0;color:var(--deep);font-style:italic;\n}\n.facts{\n  display:flex;gap:26px;flex-wrap:wrap;margin:4px 0 0;padding:10px 0 0;border-top:1px solid var(--hair-2);\n}\n.facts div{display:flex;flex-direction:column}\n.facts dt{font-variant:small-caps;text-transform:lowercase;letter-spacing:.14em;font-size:11.5px;color:var(--ink-3)}\n.facts dd{margin:0;font-size:22px;color:var(--ink);letter-spacing:.01em}\n.facts dd small{font-size:13px;color:var(--ink-3)}\n\n/* ——— controls ——— */\n.bar{\n  margin:clamp(14px,1.8vw,24px) var(--pad) 0;\n  display:flex;flex-wrap:wrap;align-items:center;gap:12px 26px;\n  padding:10px 0;border-top:1px solid var(--ink);border-bottom:1px solid var(--hair);\n}\n.ctl{display:flex;align-items:center;gap:10px}\n.ctl-label{font-variant:small-caps;text-transform:lowercase;letter-spacing:.16em;font-size:12px;color:var(--ink-3)}\n.seg{display:inline-flex;border:1px solid var(--hair);border-radius:999px;padding:2px;background:rgba(255,255,255,.35)}\n.seg button{\n  appearance:none;border:0;background:transparent;color:var(--ink-2);\n  font:inherit;font-size:14px;letter-spacing:.02em;padding:5px 14px;border-radius:999px;cursor:pointer;\n  transition:background .35s ease,color .35s ease;\n}\n.seg button[aria-pressed=\"true\"]{background:var(--deep);color:var(--lime)}\n.seg button:not([aria-pressed=\"true\"]):hover{color:var(--deep);background:rgba(11,61,92,.07)}\n.race-btn{\n  appearance:none;display:inline-flex;align-items:center;gap:9px;\n  font:inherit;font-size:14.5px;letter-spacing:.03em;color:var(--lime);\n  background:linear-gradient(180deg,#134d70,var(--deep));\n  border:1px solid #0a3450;border-radius:999px;padding:6px 16px 6px 12px;cursor:pointer;\n  box-shadow:0 1px 0 rgba(255,255,255,.25) inset,0 6px 16px -8px rgba(11,61,92,.7);\n  transition:transform .2s ease,box-shadow .3s ease;\n}\n.race-btn:hover{transform:translateY(-1px);box-shadow:0 1px 0 rgba(255,255,255,.25) inset,0 10px 20px -10px rgba(11,61,92,.8)}\n.race-btn:active{transform:translateY(0)}\n.race-btn svg{display:block}\n.race-btn[aria-pressed=\"true\"]{background:var(--lime);color:var(--deep);border-color:var(--deep)}\n.race-btn[aria-pressed=\"true\"] .drop{fill:var(--deep)}\n.readout{\n  margin-left:auto;display:flex;align-items:baseline;gap:10px;min-height:24px;\n  font-size:14px;color:var(--ink-2);text-align:right;\n}\n.odo{font-size:20px;color:var(--deep);min-width:5.2ch;text-align:right;font-variant-numeric:tabular-nums lining-nums}\n.readout em{color:var(--ink-3);font-style:italic}\n\n/* ——— chart ——— */\n.stage{margin:0 var(--pad);position:relative}\n.chart-wrap{position:relative;width:100%;min-height:200px;touch-action:pan-y;overflow:clip;overflow-clip-margin:8px}\n#chart{position:absolute;inset:0;display:block;overflow:visible}\n#flow{position:absolute;left:0;top:0;pointer-events:none}\n.hint{\n  position:absolute;right:0;top:4px;margin:0;z-index:2;font-style:italic;font-size:13px;color:var(--ink-3);pointer-events:none;\n  transition:opacity .6s ease;\n}\n.has-active .hint{opacity:0}\n\n.axis text{font-family:var(--serif);font-size:12px;fill:var(--ink-3)}\n.axis .sc{font-variant:small-caps;letter-spacing:.14em;font-size:11px}\n.axis line.grid{stroke:var(--hair);stroke-dasharray:1 5;stroke-linecap:round}\n.axis line.tick{stroke:var(--ink-3);stroke-width:.8}\n.axis line.base{stroke:var(--ink-2);stroke-width:.8}\n.groups{transition:opacity .6s ease}\n.groups text{font-family:var(--serif);font-variant:small-caps;letter-spacing:.2em;font-size:11px;fill:var(--ink-2);text-transform:lowercase}\n.groups line{stroke:var(--hair);stroke-width:1}\n\n.river{cursor:pointer;outline:none;transition:opacity .45s ease}\n.river .hit{fill:transparent}\n.river:focus-visible .hit{fill:rgba(11,61,92,.05);stroke:var(--deep);stroke-width:1;stroke-dasharray:2 3}\n.has-active .river{opacity:.22}\n.has-active .river.on{opacity:1}\n.river .rank{font-size:11.5px;fill:var(--ink-3);letter-spacing:.06em}\n.river .name{font-size:19px;fill:var(--ink)}\n.river .cont{font-size:11px;fill:var(--ink-3);font-variant:small-caps;letter-spacing:.16em;text-transform:lowercase}\n.river .len{font-size:15px;fill:var(--ink)}\n.river .len .approx{fill:var(--ink-3)}\n.river .mouth{font-size:12px;font-style:italic;fill:var(--ink-3)}\n.river .src{fill:var(--lime);stroke:var(--ink-2);stroke-width:.9}\n.river .delta path{fill:none;stroke-linecap:round}\n.river .glint{fill:none;stroke:rgba(255,255,255,.28);stroke-width:.8;stroke-linecap:round}\n.river.on .name{fill:var(--deep)}\n.river.arrived .len{fill:var(--deep)}\n.river .flag{opacity:0;transition:opacity .4s ease}\n.river.arrived .flag{opacity:1}\n.v .river .name{font-size:12.5px}\n.v .river .len{font-size:10px}\n.v .river .rank{font-size:9.5px}\n.v .axis text{font-size:9.5px}\n.v .axis .sc{font-size:9px}\n.v .groups text{font-size:9px;letter-spacing:.12em}\n\n/* tooltip */\n.tip{\n  position:fixed;left:0;top:0;z-index:30;width:min(300px,calc(100vw - 32px));\n  background:rgba(247,245,240,.97);\n  border:1px solid var(--hair);border-left:4px solid var(--deep);\n  box-shadow:0 18px 40px -22px rgba(11,40,60,.55),0 2px 6px rgba(11,40,60,.08);\n  padding:14px 16px 12px;border-radius:2px;\n  opacity:0;transform:translate3d(0,6px,0);pointer-events:none;\n  transition:opacity .22s ease,transform .22s ease;\n}\n.tip.show{opacity:1;transform:translate3d(0,0,0)}\n.tip .t-head{display:flex;justify-content:space-between;gap:10px;font-variant:small-caps;text-transform:lowercase;letter-spacing:.14em;font-size:11.5px;color:var(--ink-3)}\n.tip h2{margin:2px 0 8px;font-weight:400;font-size:25px;line-height:1.1;color:var(--deep)}\n.tip dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:14px}\n.tip dt{font-variant:small-caps;text-transform:lowercase;letter-spacing:.12em;font-size:11.5px;color:var(--ink-3);padding-top:2px}\n.tip dd{margin:0;color:var(--ink)}\n.tip .note{margin:10px 0 0;padding-top:8px;border-top:1px solid var(--hair-2);font-style:italic;font-size:13.5px;color:var(--ink-2);line-height:1.45}\n\n/* ——— legend ——— */\n.legend{\n  margin:clamp(10px,1.5vw,20px) var(--pad) 0;\n  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px 36px;\n  padding:18px 0 22px;border-top:1px solid var(--ink);border-bottom:1px solid var(--hair);\n}\n.legend h3{margin:0 0 6px;font-weight:400;font-variant:small-caps;text-transform:lowercase;letter-spacing:.18em;font-size:12.5px;color:var(--ink-2)}\n.legend p{margin:8px 0 0;font-size:14px;color:var(--ink-2);line-height:1.5}\n.ramp{height:12px;border-radius:1px;background:linear-gradient(90deg,#7fc8c2,#3f9eab 45%,#1f7a90 62%,#0b3d5c);position:relative}\n.ramp-lab{display:flex;justify-content:space-between;font-size:12.5px;color:var(--ink-3);margin-top:4px;font-style:italic}\n.scalebar{display:flex;align-items:flex-end;gap:10px;height:30px}\n.scalebar .rule{position:relative;height:9px;border:1px solid var(--ink);border-top:0;transition:width .5s ease}\n.scalebar .rule::after{content:\"\";position:absolute;left:50%;bottom:0;height:5px;border-left:1px solid var(--ink)}\n.scalebar span{font-size:14px;color:var(--ink);white-space:nowrap}\n.legend svg{display:block;max-width:100%}\n\n.notes{\n  margin:0 var(--pad);padding:18px 0 40px;\n  display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:28px;\n  font-size:14px;color:var(--ink-2);\n}\n.notes p{margin:0 0 8px;line-height:1.6}\n.notes .colophon{font-style:italic;color:var(--ink-3);text-align:right}\n.notes sup{font-size:.7em}\n\n@media (max-width:1100px){\n  .legend{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n@media (max-width:760px){\n  body{font-size:16px}\n  .mast{grid-template-columns:1fr;gap:14px}\n  .contours{left:0;width:100%;top:-10%;height:120%}\n  .intro{justify-self:start}\n  .kicker span:last-child{display:none}\n  .facts{gap:18px}\n  .facts dd{font-size:19px}\n  .bar{gap:10px 16px}\n  .readout{margin-left:0;width:100%;justify-content:flex-start;text-align:left;flex-wrap:wrap;gap:4px 8px}\n  .odo{min-width:0;text-align:left}\n  .legend{grid-template-columns:1fr;gap:16px}\n  .notes{grid-template-columns:1fr;gap:6px}\n  .notes .colophon{text-align:left}\n  .hint{position:static;text-align:right;padding:8px 0 4px;font-size:12.5px}\n}\n@media (max-width:400px){\n  .seg button{padding:5px 11px;font-size:13.5px}\n  .race-btn{font-size:13.5px}\n}\n@media (prefers-reduced-motion:reduce){\n  .wave-orn path{animation:none;stroke-dashoffset:0}\n  .river,.tip,.groups,.seg button{transition:none}\n}\n</style>\n</head>\n<body>\n<canvas id=\"paper\" aria-hidden=\"true\"></canvas>\n<a class=\"skip\" href=\"#stage\">Skip to the chart</a>\n\n<header class=\"mast\">\n  <div class=\"kicker\"><span>An atlas in ten ribbons</span><span>Plate I &nbsp;·&nbsp; Lengths approximate</span></div>\n  <div class=\"title-block\">\n    <svg class=\"contours\" viewBox=\"0 0 700 200\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n      <defs><path id=\"bend\" d=\"M-20 70 C60 40,120 40,190 78 S330 132,410 96 S540 22,620 58 S700 96,730 84\"/></defs>\n      <use href=\"#bend\" y=\"0\"/><use href=\"#bend\" y=\"9\"/><use href=\"#bend\" y=\"18\"/><use href=\"#bend\" y=\"27\"/>\n      <use href=\"#bend\" y=\"36\"/><use href=\"#bend\" y=\"45\"/><use href=\"#bend\" y=\"54\"/><use href=\"#bend\" y=\"63\"/>\n      <use href=\"#bend\" y=\"72\"/>\n    </svg>\n    <h1>Long Water</h1>\n    <p class=\"subtitle\">\n      <svg class=\"wave-orn\" width=\"58\" height=\"18\" viewBox=\"0 0 58 18\" aria-hidden=\"true\">\n        <path d=\"M1 4 C8 0,13 8,20 4 S32 0,39 4 S51 8,57 4\" fill=\"none\" stroke=\"#0b3d5c\" stroke-width=\"1.1\"/>\n        <path d=\"M1 9 C8 5,13 13,20 9 S32 5,39 9 S51 13,57 9\" fill=\"none\" stroke=\"#1f7a90\" stroke-width=\"1.1\"/>\n        <path d=\"M1 14 C8 10,13 18,20 14 S32 10,39 14 S51 18,57 14\" fill=\"none\" stroke=\"#7fc8c2\" stroke-width=\"1.1\"/>\n      </svg>\n      The world's great rivers\n    </p>\n  </div>\n  <div class=\"intro\">\n    <p>A river's length is a slippery number. Follow a different headwater, trace another channel through the delta, or survey in a wet year instead of a dry one, and the total shifts by hundreds of kilometres. These are the commonly cited, approximate figures for Earth's ten longest rivers — each drawn to the same scale, source on the left, sea on the right.</p>\n    <dl class=\"facts\">\n      <div><dt>Combined length</dt><dd id=\"factSum\">≈ 56,062 <small>km</small></dd></div>\n      <div><dt>Around the Equator</dt><dd>≈ 1.4 <small>times</small></dd></div>\n      <div><dt>Continents</dt><dd>4 <small>of 7</small></dd></div>\n    </dl>\n  </div>\n</header>\n\n<div class=\"bar\" role=\"toolbar\" aria-label=\"Chart controls\">\n  <div class=\"ctl\">\n    <span class=\"ctl-label\" id=\"sortLab\">Sort by</span>\n    <div class=\"seg\" role=\"group\" aria-labelledby=\"sortLab\">\n      <button type=\"button\" data-sort=\"length\" aria-pressed=\"true\">Length</button>\n      <button type=\"button\" data-sort=\"continent\" aria-pressed=\"false\">Continent</button>\n    </div>\n  </div>\n  <div class=\"ctl\">\n    <span class=\"ctl-label\" id=\"unitLab\">Units</span>\n    <div class=\"seg\" role=\"group\" aria-labelledby=\"unitLab\">\n      <button type=\"button\" data-unit=\"km\" aria-pressed=\"true\">km</button>\n      <button type=\"button\" data-unit=\"mi\" aria-pressed=\"false\">miles</button>\n    </div>\n  </div>\n  <button type=\"button\" class=\"race-btn\" id=\"raceBtn\" aria-pressed=\"false\">\n    <svg width=\"14\" height=\"18\" viewBox=\"0 0 14 18\" aria-hidden=\"true\"><path class=\"drop\" d=\"M7 1 C9.5 5,13 8.4,13 11.6 A6 6 0 0 1 1 11.6 C1 8.4,4.5 5,7 1Z\" fill=\"#dff3f1\"/></svg>\n    <span id=\"raceTxt\">Race the droplets</span>\n  </button>\n  <p class=\"readout\" aria-live=\"polite\"><span class=\"odo\" id=\"odo\">0</span><span id=\"odoUnit\">km travelled</span><em id=\"raceMsg\">— every droplet moves at the same speed</em></p>\n</div>\n\n<main class=\"stage\" id=\"stage\">\n  <p class=\"hint\" aria-hidden=\"true\">Hover or tap a river for its story</p>\n  <div class=\"chart-wrap\" id=\"chartWrap\">\n    <svg id=\"chart\" role=\"group\" aria-label=\"The ten longest rivers drawn to scale as meandering ribbons\"></svg>\n    <canvas id=\"flow\" aria-hidden=\"true\"></canvas>\n  </div>\n\n  <table class=\"sr-only\">\n    <caption>Approximate lengths of the ten longest rivers (sources vary)</caption>\n    <thead><tr><th scope=\"col\">Rank</th><th scope=\"col\">River</th><th scope=\"col\">Continent</th><th scope=\"col\">Length</th><th scope=\"col\">Flows into</th></tr></thead>\n    <tbody id=\"srBody\"></tbody>\n  </table>\n</main>\n\n<section class=\"legend\" aria-label=\"Legend\">\n  <div>\n    <h3>Shade</h3>\n    <div class=\"ramp\" aria-hidden=\"true\"></div>\n    <div class=\"ramp-lab\"><span>shorter</span><span>longer</span></div>\n    <p>Deeper water, longer river — the shade steps down the ranking from the Nile to the Amur.</p>\n  </div>\n  <div>\n    <h3>Width</h3>\n    <svg width=\"220\" height=\"34\" viewBox=\"0 0 220 34\" aria-hidden=\"true\">\n      <path d=\"M4 10 C40 6,70 14,110 9 S180 6,214 8 L214 12 C180 11,150 13,110 12 S40 11,4 11Z\" fill=\"#0b3d5c\"/>\n      <path d=\"M4 26 C40 23,70 29,110 24 S170 15,214 15 L214 33 C176 33,150 30,110 29 S40 27,4 27Z\" fill=\"#3f9eab\"/>\n      <text x=\"4\" y=\"6\" font-size=\"9\" fill=\"#848d92\" font-style=\"italic\">thread</text>\n    </svg>\n    <p>Each ribbon swells from source to mouth; its final width follows the square root of approximate mean discharge.</p>\n  </div>\n  <div>\n    <h3>Current</h3>\n    <svg width=\"220\" height=\"34\" viewBox=\"0 0 220 34\" aria-hidden=\"true\">\n      <path d=\"M4 15 C50 8,90 24,140 15 S200 10,214 14 L214 22 C200 18,180 24,140 23 S50 18,4 19Z\" fill=\"#1f7a90\"/>\n      <g stroke=\"#f3f1ec\" stroke-width=\"1.2\" stroke-linecap=\"round\">\n        <line x1=\"24\" y1=\"16\" x2=\"30\" y2=\"15.2\"/><line x1=\"62\" y1=\"16.4\" x2=\"68\" y2=\"17.2\"/>\n        <line x1=\"104\" y1=\"19\" x2=\"110\" y2=\"19.5\"/><line x1=\"150\" y1=\"18\" x2=\"156\" y2=\"17.2\"/>\n        <line x1=\"188\" y1=\"16.8\" x2=\"194\" y2=\"16.6\"/>\n      </g>\n      <path d=\"M204 5 L214 5 M210 2 L214 5 L210 8\" fill=\"none\" stroke=\"#848d92\" stroke-width=\"1\"/>\n    </svg>\n    <p>Drifting motes trace the direction of flow, left to right, from spring to sea.</p>\n  </div>\n  <div>\n    <h3>Scale</h3>\n    <div class=\"scalebar\"><div class=\"rule\" id=\"scaleRule\"></div><span id=\"scaleTxt\">1,000 km</span></div>\n    <p>Length along the axis is to scale. Numbers are rounded, approximate and marked ≈.</p>\n  </div>\n</section>\n\n<footer class=\"notes\">\n  <div>\n    <p>Lengths are commonly cited approximations and sources vary: a river's measured length depends on which headwater you follow, how finely you trace its meanders and delta channels, and the resolution of the map. Some surveys trace the Amazon to a more distant Andean source and rank it first — the Nile's crown is conventional rather than settled. Discharge figures are rounded long-term means near the mouth.</p>\n    <p>No European river makes the list: the Volga, Europe's longest, runs about 3,530 km.</p>\n  </div>\n  <p class=\"colophon\">Drawn with inline SVG and canvas.<br>Composed for the page, not the map.</p>\n</footer>\n\n<div class=\"tip\" id=\"tip\" role=\"tooltip\" aria-hidden=\"true\"></div>\n\n<script>\n(function(){\n'use strict';\n\nvar NS = 'http://www.w3.org/2000/svg';\nvar KM_MI = 0.621371;\nvar QMAX = 209000;\nvar RACE_SECONDS = 9;\n\nvar RIVERS = [\n  {name:'Nile', short:'Nile', km:6650, cont:'Africa', rises:'The Great Lakes region of East Africa; its farthest headwater is still debated', mouth:'Mediterranean Sea, through the delta of northern Egypt', mouthShort:'Mediterranean', q:2800, note:'The White Nile and the Blue Nile meet at Khartoum before running north through the desert.'},\n  {name:'Amazon', short:'Amazon', km:6400, cont:'South America', rises:'The Andes of southern Peru', mouth:'Atlantic Ocean, off northern Brazil', mouthShort:'Atlantic', q:209000, note:'Carries more water to the sea than any other river on Earth.'},\n  {name:'Yangtze', short:'Yangtze', km:6300, cont:'Asia', rises:'The Tanggula Mountains of the Tibetan Plateau, Qinghai', mouth:'East China Sea, at Shanghai', mouthShort:'East China Sea', q:30000, note:'The longest river to flow entirely within a single country.'},\n  {name:'Mississippi–Missouri', short:'Miss.–Missouri', km:6275, cont:'North America', rises:'The Rocky Mountains of Montana, at the Missouri’s headwaters', mouth:'Gulf of Mexico, below New Orleans', mouthShort:'Gulf of Mexico', q:16800, note:'The Missouri joins the Mississippi just north of St. Louis.'},\n  {name:'Yenisei', short:'Yenisei', km:5539, cont:'Asia', rises:'Mongolia, counting the Selenga and Angara by way of Lake Baikal', mouth:'Kara Sea, in the Arctic Ocean', mouthShort:'Kara Sea', q:19600, note:'Runs north across the breadth of Siberia to the Arctic.'},\n  {name:'Yellow River', short:'Yellow River', km:5464, cont:'Asia', rises:'The Bayan Har Mountains, Qinghai', mouth:'Bohai Sea', mouthShort:'Bohai Sea', q:2600, note:'Named for the fine loess silt it carries — one of the most sediment-laden rivers anywhere.'},\n  {name:'Ob–Irtysh', short:'Ob–Irtysh', km:5410, cont:'Asia', rises:'The Altai Mountains, at the Irtysh’s headwaters', mouth:'Kara Sea, through the long Gulf of Ob', mouthShort:'Gulf of Ob', q:12500, note:'The Gulf of Ob is one of the longest estuaries on Earth.'},\n  {name:'Paraná', short:'Paraná', km:4880, cont:'South America', rises:'The Brazilian Highlands, where the Paranaíba and Grande meet', mouth:'Río de la Plata estuary, Atlantic Ocean', mouthShort:'Río de la Plata', q:17300, note:'Joins the Uruguay River to form the broad Río de la Plata.'},\n  {name:'Congo', short:'Congo', km:4700, cont:'Africa', rises:'The highlands of northeastern Zambia, as the Chambeshi', mouth:'Atlantic Ocean, between Angola and the DR Congo', mouthShort:'Atlantic', q:41000, note:'Crosses the Equator twice on its great arc through Central Africa.'},\n  {name:'Amur', short:'Amur', km:4444, cont:'Asia', rises:'The Mongolian and Manchurian uplands, via the Argun and Shilka', mouth:'Strait of Tartary, toward the Sea of Okhotsk', mouthShort:'Strait of Tartary', q:11400, note:'For much of its course it marks the border between Russia and China.'}\n];\nvar CONTS = ['Africa','Asia','North America','South America'];\nvar CONT_SHORT = {'Africa':'Africa','Asia':'Asia','North America':'N. Am.','South America':'S. Am.'};\n\n/* ——— colour scale: #0b3d5c (longest) → #7fc8c2 (shortest) ——— */\nvar STOPS = [[11,61,92],[31,122,144],[63,158,171],[127,200,194]];\nvar STOP_T = [0,.42,.72,1];\nfunction scaleColor(t){\n  for(var k=0;k<STOPS.length-1;k++){\n    if(t<=STOP_T[k+1]){\n      var u=(t-STOP_T[k])/(STOP_T[k+1]-STOP_T[k]);\n      var a=STOPS[k],b=STOPS[k+1];\n      return [Math.round(a[0]+(b[0]-a[0])*u),Math.round(a[1]+(b[1]-a[1])*u),Math.round(a[2]+(b[2]-a[2])*u)];\n    }\n  }\n  return STOPS[STOPS.length-1];\n}\nfunction hex(c){return '#'+c.map(function(v){return ('0'+v.toString(16)).slice(-2);}).join('');}\nfunction mix(c,d,t){return [Math.round(c[0]+(d[0]-c[0])*t),Math.round(c[1]+(d[1]-c[1])*t),Math.round(c[2]+(d[2]-c[2])*t)];}\nvar LIME=[243,241,236];\n\nRIVERS.forEach(function(r,i){\n  r.i=i;\n  r.rgb=scaleColor(i/9);\n  r.color=hex(r.rgb);\n  r.pale=hex(mix(r.rgb,LIME,.62));\n  var lum=(0.2126*r.rgb[0]+0.7152*r.rgb[1]+0.0722*r.rgb[2])/255;\n  r.pStyle= lum>.55 ? 'rgba(11,61,92,0.55)' : 'rgba(246,244,238,0.82)';\n  r.ph1=i*1.73+.4; r.ph2=i*2.91+1.2; r.ph3=i*.77+2.1;\n  r.cur=0; r.target=0;\n  r.arrived=false;\n});\n\n/* ——— helpers ——— */\nfunction el(tag,attrs,parent){\n  var e=document.createElementNS(NS,tag);\n  if(attrs){for(var k in attrs){if(Object.prototype.hasOwnProperty.call(attrs,k)) e.setAttribute(k,attrs[k]);}}\n  if(parent) parent.appendChild(e);\n  return e;\n}\nfunction fmt(n){return Math.round(n).toLocaleString('en-US');}\nfunction conv(km){return state.unit==='km'?km:km*KM_MI;}\nfunction unitWord(){return state.unit==='km'?'km':'mi';}\nfunction esc(s){return String(s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}\nfunction smooth(t){t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);}\n\nvar svg=document.getElementById('chart');\nvar cvs=document.getElementById('flow');\nvar ctx=cvs.getContext('2d');\nvar wrap=document.getElementById('chartWrap');\nvar tip=document.getElementById('tip');\nvar odo=document.getElementById('odo');\nvar odoUnit=document.getElementById('odoUnit');\nvar raceMsg=document.getElementById('raceMsg');\nvar raceBtn=document.getElementById('raceBtn');\nvar raceTxt=document.getElementById('raceTxt');\n\nvar mq=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):null;\nvar state={sort:'length',unit:'km',active:-1,pinned:false,vertical:false,W:0,H:0,dpr:1,reduce:!!(mq&&mq.matches),introAt:-1,built:false};\nif(mq&&mq.addEventListener){mq.addEventListener('change',function(e){state.reduce=e.matches;});}\n\nvar G={};           // geometry parameters for the current layout\nvar layers={};      // svg layers\nvar particles=[];   // pooled current particles\nvar rings=[];       // arrival ripples\nvar race={running:false,t:0,done:false,doneAt:0,order:[]};\n\n/* ——— paper grain ——— */\nvar paper=document.getElementById('paper');\nvar grainTile=null;\nfunction makeTile(){\n  var c=document.createElement('canvas');c.width=c.height=220;\n  var g=c.getContext('2d');var im=g.createImageData(220,220);var d=im.data;\n  for(var p=0;p<d.length;p+=4){\n    var dark=Math.random()<.5;\n    d[p]=dark?60:255;d[p+1]=dark?70:255;d[p+2]=dark?70:250;\n    d[p+3]=Math.floor(Math.random()*(dark?12:18));\n  }\n  g.putImageData(im,0,0);\n  for(var s=0;s<30;s++){\n    g.fillStyle='rgba(120,110,95,'+(0.03+Math.random()*.05).toFixed(3)+')';\n    g.beginPath();g.arc(Math.random()*220,Math.random()*220,.4+Math.random()*1.3,0,6.283);g.fill();\n  }\n  return c;\n}\nfunction drawPaper(){\n  try{\n    if(!grainTile) grainTile=makeTile();\n    var w=window.innerWidth,h=window.innerHeight;\n    paper.width=w;paper.height=h;\n    var pc=paper.getContext('2d');\n    pc.fillStyle=pc.createPattern(grainTile,'repeat');\n    pc.fillRect(0,0,w,h);\n    var vg=pc.createRadialGradient(w*.5,h*.35,Math.min(w,h)*.2,w*.5,h*.5,Math.max(w,h)*.8);\n    vg.addColorStop(0,'rgba(255,255,255,0)');vg.addColorStop(1,'rgba(120,112,96,.07)');\n    pc.fillStyle=vg;pc.fillRect(0,0,w,h);\n  }catch(e){}\n}\ndrawPaper();\n\n/* ——— screen-reader table ——— */\nfunction fillTable(){\n  var tb=document.getElementById('srBody');\n  tb.innerHTML=RIVERS.map(function(r){\n    return '<tr><td>'+(r.i+1)+'</td><td>'+esc(r.name)+'</td><td>'+esc(r.cont)+'</td><td>about '+fmt(conv(r.km))+' '+unitWord()+'</td><td>'+esc(r.mouth)+'</td></tr>';\n  }).join('');\n}\n\n/* ——— ordering ——— */\nfunction orderList(){\n  if(state.sort==='length') return RIVERS.map(function(r){return r.i;});\n  var out=[];\n  CONTS.forEach(function(c){\n    RIVERS.filter(function(r){return r.cont===c;}).forEach(function(r){out.push(r.i);});\n  });\n  return out;\n}\nfunction computeTargets(){\n  var ord=orderList();\n  var groups=[];var pos=G.start;var prev=null;var cur=null;\n  ord.forEach(function(ri){\n    var r=RIVERS[ri];\n    if(state.sort==='continent' && r.cont!==prev){\n      if(!G.vertical || prev!==null) pos+=G.gap;\n      cur={cont:r.cont,from:pos,to:pos};groups.push(cur);\n    }\n    r.target=pos+G.step()/2;\n    pos+=G.step();\n    if(cur) cur.to=pos;\n    prev=r.cont;\n  });\n  return groups;\n}\n\n/* ——— geometry ——— */\nfunction mapAC(a,c){return G.vertical?[c,G.y0+a]:[G.x0+a,c];}\nfunction meander(r,a){\n  var env=smooth(a/G.envLen);\n  return env*G.amp*(0.58*Math.sin(a*G.k1+r.ph1)+0.32*Math.sin(a*G.k2+r.ph2)+0.1*Math.sin(a*G.k3+r.ph3));\n}\nfunction buildRiverGeom(r){\n  var Lp=r.km*G.scale;\n  var n=Math.ceil(Lp/G.ds)+1;\n  var gx=new Float32Array(n),gy=new Float32Array(n),nx=new Float32Array(n),ny=new Float32Array(n),w=new Float32Array(n);\n  var wm=Math.max(G.wMin,G.wMax*Math.sqrt(r.q/QMAX));\n  for(var k=0;k<n;k++){\n    var a=Math.min(Lp,k*G.ds);\n    var c=meander(r,a);\n    var dc=(meander(r,a+.5)-meander(r,a-.5));\n    var t=a/Lp;\n    var len=Math.sqrt(1+dc*dc);\n    var p=mapAC(a,c);\n    gx[k]=p[0];gy[k]=p[1];\n    if(G.vertical){nx[k]=1/len;ny[k]=-dc/len;}else{nx[k]=-dc/len;ny[k]=1/len;}\n    w[k]=G.w0+(wm-G.w0)*Math.pow(t,1.45);\n  }\n  r.Lp=Lp;r.n=n;r.gx=gx;r.gy=gy;r.nx=nx;r.ny=ny;r.w=w;r.wm=wm;\n}\nfunction ribbonPath(r,extra){\n  var n=r.n,top='',bot='',k,h,t;\n  for(k=0;k<n;k++){\n    t=k/(n-1);\n    h=(r.w[k]+(extra?extra[0]+extra[1]*t:0))/2;\n    top+=(k?'L':'M')+(r.gx[k]+r.nx[k]*h).toFixed(1)+' '+(r.gy[k]+r.ny[k]*h).toFixed(1);\n  }\n  for(k=n-1;k>=0;k--){\n    t=k/(n-1);\n    h=(r.w[k]+(extra?extra[0]+extra[1]*t:0))/2;\n    bot+='L'+(r.gx[k]-r.nx[k]*h).toFixed(1)+' '+(r.gy[k]-r.ny[k]*h).toFixed(1);\n  }\n  return top+bot+'Z';\n}\nfunction glintPath(r){\n  var d='',s=Math.floor(r.n*.08),e=Math.floor(r.n*.94);\n  for(var k=s;k<=e;k++){\n    var off=r.w[k]*.18;\n    d+=(k===s?'M':'L')+(r.gx[k]+r.nx[k]*off).toFixed(1)+' '+(r.gy[k]+r.ny[k]*off).toFixed(1);\n  }\n  return d;\n}\n\n/* ——— layout / build ——— */\nfunction layout(){\n  var W=Math.max(300,Math.round(wrap.clientWidth));\n  var v=W<700;\n  G={vertical:v,W:W,ds:v?2:3};\n  if(!v){\n    G.labelW=W>1180?250:W>900?214:188;\n    G.endPad=W>1180?156:W>900?138:118;\n    G.axisH=44;G.rowH=W>1180?50:48;G.gap=24;G.x0=G.labelW;\n    G.Lmax=W-G.labelW-G.endPad;\n    G.scale=G.Lmax/6650;\n    G.start=G.axisH;\n    G.step=function(){return G.rowH;};\n    G.H=G.axisH+G.rowH*10+G.gap*4+14;\n    G.amp=G.rowH*.19;G.wMax=Math.min(22,G.rowH*.42);G.wMin=3.4;G.w0=1.3;\n  }else{\n    G.gutter=30;G.labelH=176;G.gap=7;G.y0=G.labelH;\n    G.colL=(W-G.gutter)/10;G.colC=(W-G.gutter-G.gap*3)/10;G.colW=G.colC;\n    G.Lmax=560;G.scale=G.Lmax/6650;\n    G.start=G.gutter;\n    G.step=function(){return state.sort==='length'?G.colL:G.colC;};\n    G.H=G.labelH+G.Lmax+44;\n    G.amp=G.colC*.16;G.wMax=Math.min(19,G.colC*.58);G.wMin=3;G.w0=1.1;\n  }\n  G.k1=2*Math.PI/(G.Lmax/3.1);G.k2=2*Math.PI/(G.Lmax/7.4);G.k3=2*Math.PI/(G.Lmax/15.5);\n  G.envLen=v?16:28;\n  state.vertical=v;state.W=W;state.H=G.H;\n}\n\nfunction build(){\n  layout();\n  var W=G.W,H=G.H;\n  document.body.classList.toggle('v',G.vertical);\n  wrap.style.height=H+'px';\n  svg.setAttribute('viewBox','0 0 '+W+' '+H);\n  svg.setAttribute('width',W);svg.setAttribute('height',H);\n  var dpr=Math.min(2,window.devicePixelRatio||1);state.dpr=dpr;\n  cvs.width=Math.round(W*dpr);cvs.height=Math.round(H*dpr);\n  cvs.style.width=W+'px';cvs.style.height=H+'px';\n\n  while(svg.firstChild) svg.removeChild(svg.firstChild);\n  var defs=el('defs',null,svg);\n  var soft=el('filter',G.vertical?{id:'soft',x:'-80%',y:'-4%',width:'260%',height:'108%'}:{id:'soft',x:'-4%',y:'-80%',width:'108%',height:'260%'},defs);\n  el('feGaussianBlur',{stdDeviation:G.vertical?'1.6':'2.6'},soft);\n  layers.axis=el('g',{'class':'axis'},svg);\n  layers.groups=el('g',{'class':'groups','aria-hidden':'true'},svg);\n  layers.rivers=el('g',{'class':'rivers'},svg);\n\n  RIVERS.forEach(function(r){buildRiverGeom(r);});\n  var groups=computeTargets();\n  RIVERS.forEach(function(r){r.cur=r.target;});\n\n  RIVERS.forEach(function(r){\n    var i=r.i;\n    var grad=el('linearGradient',{id:'rg'+i,gradientUnits:'userSpaceOnUse'},defs);\n    if(G.vertical){grad.setAttribute('x1',0);grad.setAttribute('x2',0);grad.setAttribute('y1',G.y0);grad.setAttribute('y2',G.y0+r.Lp);}\n    else{grad.setAttribute('x1',G.x0);grad.setAttribute('x2',G.x0+r.Lp);grad.setAttribute('y1',0);grad.setAttribute('y2',0);}\n    el('stop',{offset:'0','stop-color':hex(mix(r.rgb,LIME,.5))},grad);\n    el('stop',{offset:'.35','stop-color':hex(mix(r.rgb,LIME,.12))},grad);\n    el('stop',{offset:'1','stop-color':r.color},grad);\n\n    var cp=el('clipPath',{id:'rc'+i},defs);\n    r.clipRect=el('rect',{x:G.vertical?-G.colW:0,y:G.vertical?0:-G.rowH,width:G.vertical?G.colW*2:W,height:G.vertical?H:G.rowH*2},cp);\n\n    var g=el('g',{'class':'river','data-i':i,tabindex:'0',role:'button'},layers.rivers);\n    r.g=g;\n    if(G.vertical) el('rect',{'class':'hit',x:-G.colW/2,y:4,width:G.colW,height:H-8,rx:2},g);\n    else el('rect',{'class':'hit',x:-4,y:-G.rowH/2+1,width:W+4,height:G.rowH-2,rx:2},g);\n\n    var flow=el('g',{'clip-path':'url(#rc'+i+')'},g);\n    el('path',{d:ribbonPath(r,G.vertical?[3,5]:[5,9]),fill:r.color,opacity:'.16',filter:'url(#soft)'},flow);\n    el('path',{d:ribbonPath(r,null),fill:'url(#rg'+i+')'},flow);\n    if(r.wm>7) el('path',{'class':'glint',d:glintPath(r)},flow);\n\n    // delta distributaries\n    var dg=el('g',{'class':'delta'},flow);\n    var aB=r.Lp-G.ds*8, cB=meander(r,aB), cE=meander(r,r.Lp);\n    [-1.5,-.5,.5,1.5].forEach(function(j){\n      var spread=r.wm*.34+3;\n      var p0=mapAC(aB,cB+j*r.wm*.12),p1=mapAC(r.Lp+2,cE+j*r.wm*.3),p2=mapAC(r.Lp+(G.vertical?7:11)+(2-Math.abs(j))*3,cE+j*spread);\n      el('path',{d:'M'+p0[0].toFixed(1)+' '+p0[1].toFixed(1)+'Q'+p1[0].toFixed(1)+' '+p1[1].toFixed(1)+' '+p2[0].toFixed(1)+' '+p2[1].toFixed(1),stroke:r.color,'stroke-width':Math.abs(j)>1?.8:1.3,opacity:Math.abs(j)>1?.55:.85},dg);\n    });\n    var sp=mapAC(0,0);\n    el('circle',{'class':'src',cx:sp[0],cy:sp[1],r:G.vertical?2:2.6},flow);\n\n    if(!G.vertical){\n      var tl=el('text',{'class':'len',x:G.x0+r.Lp+32,y:0},flow);\n      r.lenApprox=el('tspan',{'class':'approx'},tl);r.lenApprox.textContent='≈ ';\n      r.lenVal=el('tspan',null,tl);\n      var fl=el('text',{'class':'mouth',x:G.x0+r.Lp+32,y:15},flow);\n      fl.textContent='→ '+r.mouthShort;\n      var flag=el('g',{'class':'flag'},flow);\n      var fp=mapAC(r.Lp+24,0);\n      el('circle',{cx:fp[0]-2,cy:-4,r:2.6,fill:r.color},flag);\n      var t1=el('text',{'class':'rank',x:0,y:4},g);t1.textContent=('0'+(i+1)).slice(-2);\n      var t2=el('text',{'class':'name',x:30,y:4},g);t2.textContent=r.name;\n      var t3=el('text',{'class':'cont',x:31,y:19},g);t3.textContent=r.cont;\n    }else{\n      var t4=el('text',{'class':'rank',x:0,y:30,'text-anchor':'middle'},g);t4.textContent=('0'+(i+1)).slice(-2);\n      var tn=el('text',{'class':'name',transform:'translate(2,'+(G.labelH-12)+') rotate(-90)'},g);tn.textContent=r.short;\n      var tv=el('text',{'class':'len',transform:'translate(12,'+(G.labelH-12)+') rotate(-90)'},g);\n      r.lenApprox=el('tspan',{'class':'approx'},tv);r.lenApprox.textContent='≈ ';\n      r.lenVal=el('tspan',null,tv);\n      var flag2=el('g',{'class':'flag'},flow);\n      var fp2=mapAC(r.Lp+20,0);\n      el('circle',{cx:fp2[0],cy:fp2[1],r:2.4,fill:r.color},flag2);\n    }\n    placeRiver(r);\n  });\n\n  drawAxis();\n  drawGroups(groups);\n  updateUnits();\n  seedParticles();\n  hideTip(true);\n  if(!state.built){\n    state.built=true;\n    state.introAt=state.reduce?-1:performance.now();\n    if(state.introAt<0) finishIntro();\n    else RIVERS.forEach(function(r){setClip(r,0);});\n  }else{\n    finishIntro();\n  }\n}\n\nfunction placeRiver(r){\n  if(!r.g) return;\n  var v=Math.round(r.cur*10)/10;\n  if(r._placed===v) return;\n  r._placed=v;\n  r.g.setAttribute('transform',G.vertical?'translate('+v+',0)':'translate(0,'+v+')');\n}\nfunction setClip(r,p){\n  var reach=G.vertical?(G.y0+(r.Lp+40)*p):(G.x0+(r.Lp+G.endPad)*p);\n  if(G.vertical) r.clipRect.setAttribute('height',Math.max(0,reach));\n  else r.clipRect.setAttribute('width',Math.max(0,reach));\n}\nfunction finishIntro(){\n  state.introAt=-1;\n  RIVERS.forEach(function(r){if(r.g){setClip(r,1.2);}});\n}\n\nfunction drawAxis(){\n  var ax=layers.axis;\n  while(ax.firstChild) ax.removeChild(ax.firstChild);\n  var step=state.unit==='km'?1000:(G.vertical?1000:500);\n  var maxU=state.unit==='km'?6650:6650*KM_MI;\n  var perUnitPx=state.unit==='km'?G.scale:G.scale/KM_MI;\n  if(!G.vertical){\n    el('line',{'class':'base',x1:G.x0,x2:G.x0,y1:G.axisH-12,y2:G.H-10},ax);\n    var s0=el('text',{'class':'sc',x:G.x0,y:16,'text-anchor':'middle'},ax);s0.textContent='source';\n    for(var v=step;v<=maxU+1;v+=step){\n      var x=G.x0+v*perUnitPx;\n      el('line',{'class':'grid',x1:x,x2:x,y1:G.axisH-6,y2:G.H-10},ax);\n      el('line',{'class':'tick',x1:x,x2:x,y1:G.axisH-12,y2:G.axisH-6},ax);\n      var t=el('text',{x:x,y:G.axisH-18,'text-anchor':'middle'},ax);\n      t.textContent=fmt(v)+(v+step>maxU+1?' '+unitWord():'');\n    }\n  }else{\n    el('line',{'class':'base',x1:G.gutter-4,x2:G.W,y1:G.y0,y2:G.y0},ax);\n    var s1=el('text',{'class':'sc',x:G.gutter-7,y:G.y0-4,'text-anchor':'end'},ax);s1.textContent=unitWord();\n    for(var u=step;u<=maxU+1;u+=step){\n      var y=G.y0+u*perUnitPx;\n      el('line',{'class':'grid',x1:G.gutter,x2:G.W,y1:y,y2:y},ax);\n      el('line',{'class':'tick',x1:G.gutter-5,x2:G.gutter,y1:y,y2:y},ax);\n      var tt=el('text',{x:G.gutter-7,y:y+3,'text-anchor':'end'},ax);tt.textContent=(u/1000)+'k';\n    }\n  }\n}\n\nfunction drawGroups(groups){\n  var gl=layers.groups;\n  while(gl.firstChild) gl.removeChild(gl.firstChild);\n  gl.style.opacity=state.sort==='continent'?'1':'0';\n  groups.forEach(function(g){\n    if(!G.vertical){\n      var y=g.from-7;\n      var t=el('text',{x:0,y:y},gl);t.textContent=g.cont;\n      el('line',{x1:118,x2:G.W,y1:y-3.5,y2:y-3.5},gl);\n    }else{\n      var cx=(g.from+g.to)/2;\n      var t2=el('text',{x:cx,y:11,'text-anchor':'middle'},gl);t2.textContent=CONT_SHORT[g.cont];\n      el('line',{x1:g.from+2,x2:g.to-2,y1:16,y2:16},gl);\n    }\n  });\n}\n\nfunction updateUnits(){\n  var u=unitWord();\n  RIVERS.forEach(function(r){\n    if(r.lenVal) r.lenVal.textContent=fmt(conv(r.km))+(G.vertical?'':' '+u);\n    if(r.g) r.g.setAttribute('aria-label',r.name+', about '+fmt(conv(r.km))+' '+(state.unit==='km'?'kilometres':'miles')+', '+r.cont+'. Flows into the '+r.mouthShort+'. Press Enter for details.');\n  });\n  var sum=RIVERS.reduce(function(s,r){return s+r.km;},0);\n  document.getElementById('factSum').innerHTML='≈ '+fmt(conv(sum))+' <small>'+u+'</small>';\n  var unitPx=state.unit==='km'?G.scale*1000:G.scale*1000/KM_MI;\n  var len=state.unit==='km'?1000:1000;\n  document.getElementById('scaleRule').style.width=Math.round(unitPx)+'px';\n  document.getElementById('scaleTxt').textContent=fmt(len)+' '+(state.unit==='km'?'km':'miles');\n  odoUnit.textContent=u+' travelled';\n  fillTable();\n  drawAxis();\n  if(state.active>=0) showTipFor(state.active,lastPt.x,lastPt.y);\n}\n\n/* ——— particles ——— */\nfunction seedParticles(){\n  particles.length=0;\n  RIVERS.forEach(function(r){\n    var area=0;for(var k=0;k<r.n;k++) area+=r.w[k]*G.ds;\n    var count=Math.round(Math.max(G.vertical?10:18,area/(G.vertical?30:34)));\n    for(var j=0;j<count;j++){\n      particles.push({r:r.i,a:sampleA(r),u:(Math.random()*2-1)*.4,v:(G.vertical?8:13)+Math.random()*(G.vertical?10:17),tl:(G.vertical?3:4)+Math.random()*(G.vertical?4:7),b:Math.random()<.3?1:0});\n    }\n  });\n}\nfunction sampleA(r){\n  for(var tries=0;tries<12;tries++){\n    var a=Math.random()*r.Lp;\n    var k=Math.min(r.n-1,Math.floor(a/G.ds));\n    if(Math.random()<Math.sqrt(r.w[k]/r.wm)) return a;\n  }\n  return Math.random()*r.Lp;\n}\nfunction posAt(r,a,u,out){\n  var f=a/G.ds, k=Math.floor(f);\n  if(k>=r.n-1){k=r.n-2;f=r.n-1;}\n  if(k<0){k=0;f=0;}\n  var t=f-k;\n  var x=r.gx[k]+(r.gx[k+1]-r.gx[k])*t, y=r.gy[k]+(r.gy[k+1]-r.gy[k])*t;\n  var h=(r.w[k]+(r.w[k+1]-r.w[k])*t)*u*.5;\n  out[0]=x+r.nx[k]*h+(G.vertical?r.cur:0);\n  out[1]=y+r.ny[k]*h+(G.vertical?0:r.cur);\n  return out;\n}\nvar P0=[0,0],P1=[0,0];\n\n/* ——— race ——— */\nfunction startRace(){\n  race.running=true;race.t=0;race.done=false;race.order=[];rings.length=0;\n  RIVERS.forEach(function(r){r.arrived=false;if(r.g) r.g.classList.remove('arrived');});\n  raceBtn.setAttribute('aria-pressed','true');raceTxt.textContent='Stop the race';\n  raceMsg.textContent='— all ten droplets leave their sources together';\n}\nfunction stopRace(msg){\n  race.running=false;\n  raceBtn.setAttribute('aria-pressed','false');raceTxt.textContent=race.done?'Race again':'Race the droplets';\n  if(msg) raceMsg.textContent=msg;\n  RIVERS.forEach(function(r){if(r.g) r.g.classList.remove('arrived');});\n}\nfunction raceStep(dt){\n  var speed=G.Lmax/RACE_SECONDS;\n  race.t+=dt;\n  var a=race.t*speed;\n  var km=Math.min(6650,a/G.scale);\n  odo.textContent=fmt(conv(km));\n  RIVERS.forEach(function(r){\n    if(!r.arrived && a>=r.Lp){\n      r.arrived=true;race.order.push(r.i);\n      if(r.g) r.g.classList.add('arrived');\n      posAt(r,r.Lp,0,P0);\n      rings.push({x:P0[0],y:P0[1],t:0,c:r.color});\n      var place=race.order.length;\n      if(place===1) raceMsg.textContent='— the '+r.name+' reaches the '+r.mouthShort+' first';\n      else if(place<10) raceMsg.textContent='— '+r.name+' arrives ('+ordinal(place)+')';\n    }\n  });\n  if(race.order.length===10 && !race.done){\n    race.done=true;race.doneAt=race.t;\n    var first=RIVERS[race.order[0]],last=RIVERS[race.order[9]];\n    raceMsg.textContent='— the '+last.name+' arrives last, '+fmt(conv(last.km-first.km))+' '+unitWord()+' after the '+first.name;\n  }\n  if(race.done && race.t-race.doneAt>2.6){\n    stopRace(null);\n  }\n}\nfunction ordinal(n){var s=['th','st','nd','rd'],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0]);}\n\n/* ——— tooltip ——— */\nvar lastPt={x:0,y:0};\nfunction tipHTML(r){\n  return '<div class=\"t-head\"><span>No. '+(r.i+1)+' by length</span><span>'+esc(r.cont)+'</span></div>'+\n    '<h2>'+esc(r.name)+'</h2>'+\n    '<dl><dt>Length</dt><dd>≈ '+fmt(conv(r.km))+' '+(state.unit==='km'?'km':'miles')+' <span style=\"color:#848d92\">('+(state.unit==='km'?fmt(r.km*KM_MI)+' mi':fmt(r.km)+' km')+')</span></dd>'+\n    '<dt>Rises</dt><dd>'+esc(r.rises)+'</dd>'+\n    '<dt>Flows out</dt><dd>'+esc(r.mouth)+'</dd>'+\n    '<dt>Discharge</dt><dd>≈ '+fmt(r.q)+' m³/s, mean</dd></dl>'+\n    '<p class=\"note\">'+esc(r.note)+'</p>';\n}\nfunction showTipFor(i,x,y){\n  var r=RIVERS[i];\n  clearTimeout(tipPark);\n  tip.innerHTML=tipHTML(r);\n  tip.style.borderLeftColor=r.color;\n  tip.classList.add('show');tip.setAttribute('aria-hidden','false');\n  positionTip(x,y);\n}\nfunction positionTip(x,y){\n  var tw=tip.offsetWidth,th=tip.offsetHeight,vw=window.innerWidth,vh=window.innerHeight;\n  var left=x+18,top=y+18;\n  if(left+tw>vw-12) left=x-tw-18;\n  if(left<12) left=Math.max(12,Math.min(vw-tw-12,x-tw/2));\n  if(top+th>vh-12) top=y-th-18;\n  if(top<12) top=12;\n  tip.style.transform='';\n  tip.style.left=Math.round(left)+'px';tip.style.top=Math.round(top)+'px';\n}\nvar tipPark=0;\nfunction hideTip(force){\n  tip.classList.remove('show');tip.setAttribute('aria-hidden','true');\n  clearTimeout(tipPark);\n  // park the hidden tooltip at the origin so it can never widen the page\n  tipPark=setTimeout(function(){if(!tip.classList.contains('show')){tip.style.left='0px';tip.style.top='0px';}},force?0:260);\n  if(force){setActive(-1);state.pinned=false;}\n}\nfunction setActive(i){\n  if(state.active===i) return;\n  state.active=i;\n  RIVERS.forEach(function(r){if(r.g) r.g.classList.toggle('on',r.i===i);});\n  document.body.classList.toggle('has-active',i>=0);\n  wrap.classList.toggle('has-active',i>=0);\n}\nfunction riverFromEvent(e){\n  var t=e.target;\n  while(t && t!==svg){\n    if(t.classList && t.classList.contains('river')) return +t.getAttribute('data-i');\n    t=t.parentNode;\n  }\n  return -1;\n}\nsvg.addEventListener('pointermove',function(e){\n  if(e.pointerType==='touch') return;\n  var i=riverFromEvent(e);\n  lastPt.x=e.clientX;lastPt.y=e.clientY;\n  if(state.pinned && i!==state.active && i<0) return;\n  if(i>=0){state.pinned=false;setActive(i);showTipFor(i,e.clientX,e.clientY);}\n  else if(!state.pinned){setActive(-1);hideTip();}\n});\nsvg.addEventListener('pointerleave',function(e){\n  if(e.pointerType==='touch'||state.pinned) return;\n  setActive(-1);hideTip();\n});\nsvg.addEventListener('pointerdown',function(e){\n  var i=riverFromEvent(e);\n  lastPt.x=e.clientX;lastPt.y=e.clientY;\n  if(i<0){hideTip(true);return;}\n  if(e.pointerType==='touch' && state.active===i && state.pinned){hideTip(true);return;}\n  state.pinned=(e.pointerType==='touch');\n  setActive(i);showTipFor(i,e.clientX,e.clientY);\n});\ndocument.addEventListener('pointerdown',function(e){\n  if(!svg.contains(e.target) && state.active>=0 && !tip.contains(e.target)) hideTip(true);\n});\nsvg.addEventListener('focusin',function(e){\n  var i=riverFromEvent(e);if(i<0) return;\n  var b=RIVERS[i].g.getBoundingClientRect();\n  lastPt.x=G.vertical?b.left+b.width/2:b.left+Math.min(b.width*.55,G.x0+RIVERS[i].Lp*.6);\n  lastPt.y=G.vertical?b.top+140:b.top+b.height/2;\n  setActive(i);state.pinned=true;showTipFor(i,lastPt.x,lastPt.y);\n});\nsvg.addEventListener('focusout',function(e){\n  if(!svg.contains(e.relatedTarget)) hideTip(true);\n});\nsvg.addEventListener('keydown',function(e){\n  var i=riverFromEvent(e);if(i<0) return;\n  if(e.key==='Escape'){hideTip(true);e.target.blur();}\n  if(e.key==='Enter'||e.key===' '){e.preventDefault();if(tip.classList.contains('show')) hideTip(false);else showTipFor(i,lastPt.x,lastPt.y);}\n  if(e.key==='ArrowDown'||e.key==='ArrowRight'||e.key==='ArrowUp'||e.key==='ArrowLeft'){\n    e.preventDefault();\n    var ord=orderList();var k=ord.indexOf(i);\n    k+= (e.key==='ArrowDown'||e.key==='ArrowRight')?1:-1;\n    k=(k+10)%10;RIVERS[ord[k]].g.focus();\n  }\n});\nwindow.addEventListener('scroll',function(){if(state.active>=0&&!state.pinned){hideTip(true);}},{passive:true});\ndocument.addEventListener('keydown',function(e){if(e.key==='Escape') hideTip(true);});\n\n/* ——— controls ——— */\nArray.prototype.forEach.call(document.querySelectorAll('[data-sort]'),function(b){\n  b.addEventListener('click',function(){\n    if(state.sort===b.getAttribute('data-sort')) return;\n    state.sort=b.getAttribute('data-sort');\n    Array.prototype.forEach.call(document.querySelectorAll('[data-sort]'),function(o){o.setAttribute('aria-pressed',String(o===b));});\n    var groups=computeTargets();\n    drawGroups(groups);\n    if(state.reduce) RIVERS.forEach(function(r){r.cur=r.target;placeRiver(r);});\n    hideTip(true);\n  });\n});\nArray.prototype.forEach.call(document.querySelectorAll('[data-unit]'),function(b){\n  b.addEventListener('click',function(){\n    state.unit=b.getAttribute('data-unit');\n    Array.prototype.forEach.call(document.querySelectorAll('[data-unit]'),function(o){o.setAttribute('aria-pressed',String(o===b));});\n    updateUnits();\n    if(!race.running) odo.textContent='0';\n  });\n});\nraceBtn.addEventListener('click',function(){\n  if(race.running){race.done=false;stopRace('— race stopped; press again to restart');odo.textContent='0';}\n  else startRace();\n});\n\n/* ——— frame loop ——— */\nvar last=performance.now();\nfunction frame(now){\n  var dt=Math.min(.05,(now-last)/1000);last=now;\n  if(document.hidden){requestAnimationFrame(frame);return;}\n\n  // intro reveal\n  if(state.introAt>=0){\n    var el0=now-state.introAt,allDone=true;\n    RIVERS.forEach(function(r){\n      var p=(el0-r.i*42)/1000;\n      if(p<1) allDone=false;\n      p=Math.max(0,Math.min(1,p));\n      setClip(r,1-Math.pow(1-p,3));\n    });\n    if(allDone) finishIntro();\n  }\n\n  // glide rows to targets\n  var k=1-Math.exp(-dt*7.5);\n  RIVERS.forEach(function(r){\n    var d=r.target-r.cur;\n    if(Math.abs(d)>.05){r.cur+=d*k;placeRiver(r);}\n    else if(d!==0){r.cur=r.target;placeRiver(r);}\n  });\n\n  if(race.running) raceStep(dt);\n\n  draw(dt);\n  requestAnimationFrame(frame);\n}\n\nfunction draw(dt){\n  var dpr=state.dpr;\n  ctx.setTransform(dpr,0,0,dpr,0,0);\n  ctx.clearRect(0,0,G.W,G.H);\n  var motion=state.reduce?.12:1;\n  var introFade=state.introAt>=0?Math.max(0,Math.min(1,(performance.now()-state.introAt-700)/700)):1;\n  ctx.lineCap='round';\n  var active=state.active;\n  var byRiver=[];\n  for(var q=0;q<10;q++) byRiver.push([]);\n  for(var j=0;j<particles.length;j++) byRiver[particles[j].r].push(particles[j]);\n  for(var ri=0;ri<10;ri++){\n    var r=RIVERS[ri];\n    var list=byRiver[ri];\n    var alpha=(active<0||active===ri)?1:.15;\n    if(race.running) alpha*=.35;\n    alpha*=introFade;\n    ctx.strokeStyle=r.pStyle;\n    for(var b=0;b<2;b++){\n      ctx.lineWidth=b?(G.vertical?1.3:1.7):(G.vertical?.7:.9);\n      ctx.globalAlpha=alpha*(b?.9:.6);\n      ctx.beginPath();\n      for(var m=0;m<list.length;m++){\n        var p=list[m];\n        if(p.b!==b) continue;\n        p.a+=p.v*dt*motion;\n        if(p.a>r.Lp){p.a=Math.random()*r.Lp*.08;p.u=(Math.random()*2-1)*.4;}\n        var tailA=Math.max(0,p.a-p.tl);\n        posAt(r,p.a,p.u,P0);posAt(r,tailA,p.u,P1);\n        ctx.moveTo(P1[0],P1[1]);ctx.lineTo(P0[0],P0[1]);\n      }\n      ctx.stroke();\n    }\n  }\n  ctx.globalAlpha=1;\n\n  if(race.running) drawRace();\n  // ripples\n  for(var z=rings.length-1;z>=0;z--){\n    var g=rings[z];g.t+=dt;\n    if(g.t>1.6){rings.splice(z,1);continue;}\n    var e=g.t/1.6;\n    ctx.globalAlpha=(1-e)*.8;\n    ctx.strokeStyle=g.c;ctx.lineWidth=1.2;\n    ctx.beginPath();ctx.arc(g.x,g.y,4+e*22,0,Math.PI*2);ctx.stroke();\n    ctx.globalAlpha=(1-e)*.45;\n    ctx.beginPath();ctx.arc(g.x,g.y,2+e*12,0,Math.PI*2);ctx.stroke();\n  }\n  ctx.globalAlpha=1;\n}\n\nfunction drawRace(){\n  var speed=G.Lmax/RACE_SECONDS;\n  var a=race.t*speed;\n  var fade=race.done?Math.max(0,1-(race.t-race.doneAt)/2.6):1;\n  // the front line\n  var frontA=Math.min(a,G.Lmax);\n  ctx.save();\n  ctx.globalAlpha=.55*fade;\n  ctx.strokeStyle='#1c272e';ctx.lineWidth=.8;ctx.setLineDash([2,4]);\n  ctx.beginPath();\n  if(G.vertical){var fy=G.y0+frontA;ctx.moveTo(G.gutter,fy);ctx.lineTo(G.W,fy);}\n  else{var fx=G.x0+frontA;ctx.moveTo(fx,G.axisH-8);ctx.lineTo(fx,G.H-10);}\n  ctx.stroke();ctx.restore();\n\n  RIVERS.forEach(function(r){\n    var head=Math.min(a,r.Lp);\n    var trail=G.vertical?46:78;\n    var segs=14;\n    ctx.lineCap='round';\n    for(var s=0;s<segs;s++){\n      var a1=head-trail*(s+1)/segs,a0=head-trail*s/segs;\n      if(a0<=0) break;\n      posAt(r,Math.max(0,a1),0,P1);posAt(r,a0,0,P0);\n      ctx.globalAlpha=(1-s/segs)*.85*fade;\n      ctx.strokeStyle='#ffffff';\n      ctx.lineWidth=(G.vertical?2.2:2.8)*(1-s/segs*.7);\n      ctx.beginPath();ctx.moveTo(P1[0],P1[1]);ctx.lineTo(P0[0],P0[1]);ctx.stroke();\n    }\n    posAt(r,head,0,P0);\n    ctx.globalAlpha=.28*fade;ctx.fillStyle='#ffffff';\n    ctx.beginPath();ctx.arc(P0[0],P0[1],G.vertical?7:10,0,Math.PI*2);ctx.fill();\n    ctx.globalAlpha=fade;\n    ctx.fillStyle='#ffffff';ctx.strokeStyle=r.arrived?'#0b3d5c':r.color;ctx.lineWidth=1.6;\n    ctx.beginPath();ctx.arc(P0[0],P0[1],G.vertical?3.2:4.4,0,Math.PI*2);ctx.fill();ctx.stroke();\n  });\n  ctx.globalAlpha=1;\n}\n\n/* ——— resize ——— */\nvar rsz=0,lastW=0,paperT=0;\nfunction onResize(){\n  cancelAnimationFrame(rsz);\n  rsz=requestAnimationFrame(function(){\n    var w=Math.round(wrap.clientWidth);\n    var d=Math.min(2,window.devicePixelRatio||1);\n    if(w===lastW && d===state.dpr) return;\n    lastW=w;\n    build();\n    if(race.running){race.done=false;stopRace('— race reset after resize');odo.textContent='0';}\n  });\n}\nwindow.addEventListener('resize',onResize);\nwindow.addEventListener('resize',function(){clearTimeout(paperT);paperT=setTimeout(drawPaper,120);});\nif(window.ResizeObserver){new ResizeObserver(onResize).observe(wrap);}\n\nbuild();lastW=Math.round(wrap.clientWidth);\nrequestAnimationFrame(function(t){last=t;requestAnimationFrame(frame);});\n})();\n</script>\n</body>\n</html>\n";
